// ---- Biblioteca: QR Code ----
// A LEITURA do QR é feita pelo serviço leitor-qr do laboratório (imagens e PDFs). Aqui ficam:
//  - QR "desenhado" sem imagem (tabela HTML com células pretas, ou caracteres █ ▀ ▄): vira uma matriz de
//    módulos e depois uma imagem PGM simples, que vai para o mesmo leitor. É truque para fugir de filtro de imagem.
//  - leitura do código PIX ("copia e cola", padrão EMV do Banco Central) que um QR pode trazer no lugar de um link.

const LADO_MINIMO_QR = 21; // QR versão 1

// Cor de fundo de uma célula: bgcolor="#000", style="background:#000000", rgb(0,0,0), black/white.
function celulaEscura(atributos) {
  const a = String(atributos ?? '').toLowerCase();
  const cor = (a.match(/bgcolor\s*=\s*["']?\s*([#a-z0-9]+)/) ?? a.match(/background(?:-color)?\s*:\s*([^;"']+)/) ?? [])[1];
  if (!cor) return false;
  const c = cor.trim();
  if (/^(black|#000|#000000)$/.test(c)) return true;
  if (/^(white|#fff|#ffffff|transparent|none)$/.test(c)) return false;
  let r; let g; let b;
  const hex = c.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/);
  const rgb = c.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
  if (hex) {
    const h = hex[1].length === 3 ? hex[1].split('').map((x) => x + x).join('') : hex[1];
    [r, g, b] = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
  } else if (rgb) {
    [r, g, b] = rgb.slice(1, 4).map(Number);
  } else {
    return false;
  }
  return 0.299 * r + 0.587 * g + 0.114 * b < 128;
}

function pareceMatrizQr(m) {
  if (m.length < LADO_MINIMO_QR) return false;
  const largura = m[0].length;
  if (largura < LADO_MINIMO_QR || m.some((l) => l.length !== largura) || Math.abs(largura - m.length) > 2) return false;
  const escuros = m.reduce((t, l) => t + l.filter(Boolean).length, 0) / (largura * m.length);
  return escuros > 0.25 && escuros < 0.75;
}

// <table> com uma célula por módulo (cores de fundo). Devolve as matrizes que parecem QR.
function matrizesDeTabelas(html) {
  const achadas = [];
  for (const t of String(html ?? '').matchAll(/<table\b[^>]*>([\s\S]*?)<\/table\s*>/gi)) {
    const linhas = [];
    for (const tr of t[1].matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr\s*>/gi)) {
      const celulas = Array.from(tr[1].matchAll(/<td\b([^>]*)>/gi), (td) => celulaEscura(td[1]));
      if (celulas.length) linhas.push(celulas);
    }
    if (pareceMatrizQr(linhas)) achadas.push(linhas);
    if (achadas.length >= 3) break;
  }
  return achadas;
}

// Linhas feitas só de █ ▀ ▄ e espaço. Meio-bloco (▀ ▄): cada linha de texto = 2 linhas de módulos.
// Só █: cada caractere = 1 módulo; se todo trecho tiver tamanho par ("██"), cada módulo usou 2 caracteres.
function matrizesDeBlocos(texto) {
  const achadas = [];
  const linhas = String(texto ?? '').replace(/ /g, ' ').split(/\r?\n/);
  let bloco = [];
  const fecha = () => {
    if (bloco.length >= 10) {
      const meio = bloco.some((l) => /[▀▄]/.test(l));
      const largura = Math.max(...bloco.map((l) => l.length));
      const cheias = bloco.map((l) => l.padEnd(largura, ' '));
      let m = [];
      if (meio) {
        for (const l of cheias) {
          m.push(Array.from(l, (c) => c === '█' || c === '▀'));
          m.push(Array.from(l, (c) => c === '█' || c === '▄'));
        }
      } else {
        m = cheias.map((l) => Array.from(l, (c) => c === '█'));
        const trechos = cheias.join('\n').match(/█+| +/g) ?? [];
        if (trechos.length && trechos.every((x) => x.length % 2 === 0)) m = m.map((l) => l.filter((_, i) => i % 2 === 0));
      }
      // Tira linhas/colunas vazias da borda (zona de silêncio) para a checagem de formato.
      while (m.length && !m[0].some(Boolean)) m.shift();
      while (m.length && !m[m.length - 1].some(Boolean)) m.pop();
      if (m.length) {
        const ini = Math.min(...m.map((l) => (l.indexOf(true) < 0 ? Infinity : l.indexOf(true))));
        const fim = Math.max(...m.map((l) => l.lastIndexOf(true)));
        m = m.map((l) => l.slice(ini, fim + 1));
      }
      if (pareceMatrizQr(m)) achadas.push(m);
    }
    bloco = [];
  };
  for (const l of linhas) {
    const limpa = l.replace(/\s+$/, '');
    if (limpa.length >= 10 && /^[█▀▄ ]+$/.test(limpa) && /[█▀▄]/.test(limpa)) bloco.push(limpa);
    else fecha();
  }
  fecha();
  return achadas.slice(0, 3);
}

// Matriz -> imagem PGM (P5, tons de cinza), com 4 módulos de margem branca e 6 pixels por módulo.
function matrizParaPgm(m, escala = 6, margem = 4) {
  const lado = (m[0].length + 2 * margem) * escala;
  const alto = (m.length + 2 * margem) * escala;
  const cabecalho = `P5\n${lado} ${alto}\n255\n`;
  const bytes = Array.from(cabecalho, (c) => c.charCodeAt(0));
  for (let y = 0; y < alto; y++) {
    const linha = m[Math.floor(y / escala) - margem];
    for (let x = 0; x < lado; x++) {
      const escuro = linha ? linha[Math.floor(x / escala) - margem] : false;
      bytes.push(escuro ? 0 : 255);
    }
  }
  return bytes;
}

// bytes -> base64 (feito à mão: a sandbox do n8n pode não ter Buffer).
function bytesParaBase64(bytes) {
  const tabela = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const partes = [];
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
    partes.push(tabela[(n >> 18) & 63] + tabela[(n >> 12) & 63]
      + (i + 1 < bytes.length ? tabela[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? tabela[n & 63] : '='));
  }
  return partes.join('');
}

// Código PIX (BR Code / EMV): campos ID(2) + tamanho(2) + valor. Devolve recebedor, chave, valor e cidade.
function lerPix(texto) {
  const t = String(texto ?? '').trim();
  if (!t.startsWith('000201') || !/br\.gov\.bcb\.pix/i.test(t)) return null;
  const campos = (s) => {
    const saida = {};
    for (let i = 0; i + 4 <= s.length;) {
      const id = s.slice(i, i + 2);
      const tam = Number(s.slice(i + 2, i + 4));
      if (!Number.isFinite(tam)) break;
      saida[id] = s.slice(i + 4, i + 4 + tam);
      i += 4 + tam;
    }
    return saida;
  };
  const c = campos(t);
  const conta = campos(c['26'] ?? '');
  const adicional = campos(c['62'] ?? '');
  return {
    recebedor: linha(c['59'] ?? '', 60), cidade: linha(c['60'] ?? '', 40), valor: linha(c['54'] ?? '', 20),
    chave: linha(conta['01'] ?? '', 80), url: linha(conta['25'] ?? '', 120), txid: linha(adicional['05'] ?? '', 40),
  };
}
// ---- fim da biblioteca ----

// Nó "Lista imagens e PDFs (QR)": separa do e-mail suspeito o que pode ter QR Code, para o leitor-qr do laboratório:
//  - imagens e PDFs anexados ao .eml (inclusive as imagens do corpo, "inline");
//  - QR "desenhado" sem imagem (tabela HTML ou caracteres █ ▀ ▄), convertido aqui em imagem PGM.
// Cada item vira um pedido ao leitor (nó "Lê os QR Codes"). Sem nada para ler: um item marcador, e o fluxo
// segue direto para "Extrai as evidências". Nada é aberto aqui: os bytes só são copiados em base64.
const cfg = $('Configuração').first().json;
const todos = (nome) => { try { return $(nome).all().map((i) => i.json); } catch (erro) { return []; } };
const MAX_ARQUIVOS = Number(cfg.maxArquivosQr) || 4;
const MAX_BYTES = 4 * 1024 * 1024;

const escolhidos = todos('Escolhe o que baixar');
const baixados = todos('Baixa os anexos');
let mime = null;
for (const [i, d] of escolhidos.entries()) {
  const conteudo = d.baixar ? String(baixados[i]?.body ?? baixados[i]?.data ?? '') : '';
  if (!conteudo || /\.msg$/i.test(d.nome)) continue;
  const leitura = analisarMime(conteudo);
  if (leitura.cabecalhos.some((c) => ['from', 'received', 'subject'].includes(c.nome))) {
    mime = leitura;
    while (mime.internas.length) mime = mime.internas[0]; // e-mail encaminhado como anexo: vale o de dentro
    break;
  }
}

const pedidos = [];
if (mime) {
  const ehImagem = (a) => /^image\/(png|jpe?g|gif|bmp|webp|tiff)$/i.test(a.tipo) || /^(png|jpe?g|gif|bmp|webp|tiff?)$/.test(extensoes(a.nome).pop() ?? '');
  const ehPdf = (a) => /pdf/i.test(a.tipo) || extensoes(a.nome).pop() === 'pdf' || String.fromCharCode(...a.bytes.slice(0, 5)) === '%PDF-';
  for (const a of mime.anexos) {
    if (pedidos.length >= MAX_ARQUIVOS) break;
    if (!a.bytes?.length || a.bytes.length < 100 || a.bytes.length > MAX_BYTES || !(ehImagem(a) || ehPdf(a))) continue;
    pedidos.push({ nome: linha(a.nome, 120), tipo: a.tipo, tamanho: a.bytes.length, desenhado: false, dados: bytesParaBase64(a.bytes) });
  }
  const html = mime.textos.filter((t) => t.tipo === 'text/html').map((t) => t.conteudo).join('\n');
  const texto = mime.textos.filter((t) => t.tipo === 'text/plain').map((t) => t.conteudo).join('\n');
  const desenhos = [...matrizesDeTabelas(html), ...matrizesDeBlocos(texto), ...matrizesDeBlocos(htmlParaTexto(html))];
  const vistos = new Set();
  for (const m of desenhos) {
    const chave = m.map((l) => l.map(Number).join('')).join('|');
    if (vistos.has(chave) || pedidos.length >= MAX_ARQUIVOS + 2) continue;
    vistos.add(chave);
    const pgm = matrizParaPgm(m);
    pedidos.push({ nome: `qr-desenhado-${vistos.size}.pgm`, tipo: 'image/x-portable-graymap', tamanho: pgm.length, desenhado: true, dados: bytesParaBase64(pgm) });
  }
}

if (!pedidos.length) return [{ json: { nenhum: true } }];
return pedidos.map((p) => ({ json: p }));

// ---- Biblioteca: endereços IP que não são públicos (privados, locais, reservados, documentação) ----
// Usada para ignorar IPs internos nos cabeçalhos Received e nos links (não são indicadores de ataque).

// Converte "a.b.c.d" em número (0 a 2^32-1). Devolve null se não for IPv4 válido.
function ipv4ParaNumero(ip) {
  const partes = String(ip).split('.');
  if (partes.length !== 4) return null;
  let numero = 0;
  for (const parte of partes) {
    if (!/^\d{1,3}$/.test(parte)) return null;
    const valor = Number(parte);
    if (valor > 255) return null;
    numero = numero * 256 + valor;
  }
  return numero;
}

// Faixas IPv4 privadas, locais, reservadas ou de documentação.
const FAIXAS_IPV4_BLOQUEADAS = [
  ['0.0.0.0', 8],       // "esta rede"
  ['10.0.0.0', 8],      // privada
  ['100.64.0.0', 10],   // CGNAT
  ['127.0.0.0', 8],     // loopback
  ['169.254.0.0', 16],  // link-local (inclui metadados de nuvem 169.254.169.254)
  ['172.16.0.0', 12],   // privada (inclui as redes do Docker)
  ['192.0.0.0', 24],    // IETF
  ['192.0.2.0', 24],    // documentação
  ['192.88.99.0', 24],  // 6to4 relay
  ['192.168.0.0', 16],  // privada
  ['198.18.0.0', 15],   // testes de desempenho
  ['198.51.100.0', 24], // documentação
  ['203.0.113.0', 24],  // documentação
  ['224.0.0.0', 4],     // multicast
  ['240.0.0.0', 4],     // reservada e broadcast
];

function ipv4Bloqueado(ip) {
  const numero = ipv4ParaNumero(ip);
  if (numero === null) return true;
  return FAIXAS_IPV4_BLOQUEADAS.some(([base, bits]) => {
    const mascara = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
    return ((numero & mascara) >>> 0) === ((ipv4ParaNumero(base) & mascara) >>> 0);
  });
}

// Expande um IPv6 para 8 grupos numéricos. Devolve null se for inválido.
function expandirIPv6(ip) {
  let texto = String(ip).replace(/^\[|\]$/g, '').toLowerCase();
  const zona = texto.indexOf('%');
  if (zona >= 0) texto = texto.slice(0, zona);
  const comIPv4 = texto.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (comIPv4) {
    const numero = ipv4ParaNumero(comIPv4[2]);
    if (numero === null) return null;
    texto = comIPv4[1] + (numero >>> 16).toString(16) + ':' + (numero & 0xffff).toString(16);
  }
  const metades = texto.split('::');
  if (metades.length > 2) return null;
  const esquerda = metades[0] ? metades[0].split(':') : [];
  const direita = metades.length === 2 && metades[1] ? metades[1].split(':') : [];
  const faltam = 8 - esquerda.length - direita.length;
  if (metades.length === 1 && faltam !== 0) return null;
  if (metades.length === 2 && faltam < 1) return null;
  const grupos = [...esquerda, ...Array(metades.length === 2 ? faltam : 0).fill('0'), ...direita];
  if (grupos.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
  return grupos.map((g) => parseInt(g, 16));
}

function ipv6Bloqueado(ip) {
  const g = expandirIPv6(ip);
  if (!g) return true;
  const ipv4Embutido = () => `${g[6] >> 8}.${g[6] & 255}.${g[7] >> 8}.${g[7] & 255}`;
  // IPv4 mapeado (::ffff:a.b.c.d) e NAT64 (64:ff9b::a.b.c.d): vale a regra do IPv4 embutido.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return ipv4Bloqueado(ipv4Embutido());
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return ipv4Bloqueado(ipv4Embutido());
  // Só aceita endereços globais (2000::/3). Isso já exclui ::1, fc00::/7, fe80::/10 e multicast.
  if ((g[0] & 0xe000) !== 0x2000) return true;
  if (g[0] === 0x2001 && (g[1] === 0x0db8 || g[1] === 0)) return true; // documentação e Teredo
  if (g[0] === 0x2002) return true; // 6to4 (embute um IPv4 qualquer)
  return false;
}

function ehIPv4(texto) {
  return ipv4ParaNumero(texto) !== null;
}

function ipBloqueado(ip) {
  return String(ip).includes(':') ? ipv6Bloqueado(ip) : ipv4Bloqueado(ip);
}
// ---- fim da biblioteca ----

// ---- Biblioteca: texto seguro ----
// Tudo o que vem do chamado e do e-mail suspeito foi escrito por um usuário ou por um ATACANTE.
// Por isso: esc() antes de ir para o Telegram/GLPI (vira texto, nunca HTML) e desarmar() nos
// indicadores (hxxps://site[.]com), para o analista não abrir um link malicioso sem querer.

const ENTIDADES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ordm: 'º', ordf: 'ª', euro: '€', copy: '©', reg: '®', ndash: '–', mdash: '—', hellip: '…', laquo: '«', raquo: '»' };
// Letras acentuadas do português: &aacute; &Atilde; &ccedil; ...
for (const [letras, acento, base] of [['aeiou', 'acute', 0x301], ['aeiou', 'grave', 0x300], ['aeiou', 'circ', 0x302], ['aon', 'tilde', 0x303], ['aeiou', 'uml', 0x308], ['c', 'cedil', 0x327]]) {
  for (const l of letras) {
    ENTIDADES[l + acento] = (l + String.fromCharCode(base)).normalize('NFC');
    ENTIDADES[l.toUpperCase() + acento] = (l.toUpperCase() + String.fromCharCode(base)).normalize('NFC');
  }
}

function decodificarEntidades(texto) {
  return String(texto ?? '').replace(/&(#x[0-9a-f]{1,6}|#\d{1,7}|[a-z]{2,8});/gi, (inteiro, e) => {
    if (e[0] === '#') {
      const n = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return n > 0 && n < 0x110000 && !(n >= 0xd800 && n <= 0xdfff) ? String.fromCodePoint(n) : inteiro;
    }
    return ENTIDADES[e] ?? ENTIDADES[e.toLowerCase()] ?? inteiro;
  });
}

// HTML -> texto. O GLPI guarda o conteúdo do chamado com as tags escapadas (&lt;p&gt;): desfaz isso antes.
function htmlParaTexto(html) {
  let s = String(html ?? '');
  if (/&lt;\/?[a-z][\s\S]*?&gt;/i.test(s) && !/<\/?[a-z][^>]*>/i.test(s)) s = decodificarEntidades(s);
  s = s.replace(/<(script|style|head|title)\b[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d|blockquote|table)\s*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ');
  return decodificarEntidades(s)
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Escapa para HTML do Telegram e do GLPI (o Telegram só reconhece &, < e >; " protege atributos).
function esc(texto) {
  return String(texto ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Corta o texto e remove caracteres de controle (mantém quebras de linha).
function curto(texto, maximo = 200) {
  const t = String(texto ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f​-‏‪-‮⁦-⁩]/g, '').trim();
  return t.length > maximo ? t.slice(0, maximo - 1) + '…' : t;
}

// Uma linha só (sem quebras), cortada.
function linha(texto, maximo = 200) {
  return curto(String(texto ?? '').replace(/\s+/g, ' '), maximo);
}

// Indicador "desarmado": https://mal.com/x -> hxxps://mal[.]com/x ; a@mal.com -> a[@]mal[.]com ; 1.2.3.4 -> 1.2.3[.]4
function desarmar(ioc) {
  const texto = String(ioc ?? '');
  const url = texto.match(/^([a-z][a-z0-9+.-]*)(:\/\/)([^/?#]*)(.*)$/i);
  if (url) return url[1].replace(/^http/i, (p) => p[0] + 'xx' + p[3]) + url[2] + url[3].replace(/\./g, '[.]').replace(/@/g, '[@]') + url[4];
  return texto.replace(/@/g, '[@]').replace(/\.(?=[^.]*$)/, '[.]');
}

function unicos(lista, maximo = 50) {
  const vistos = new Set();
  const saida = [];
  for (const item of lista) {
    const chave = String(item).toLowerCase();
    if (!item || vistos.has(chave)) continue;
    vistos.add(chave);
    saida.push(item);
    if (saida.length >= maximo) break;
  }
  return saida;
}
