}
if (de.dominio && WEBMAIL_GRATUITO.has(de.dominio) && (imitada || /\b(banco|suporte|equipe|financeiro|rh|ti|seguran[cç]a|atendimento|diretor|ceo|presidente)\b/i.test(de.nome))) {
