const conhecido = (d) => MARCAS.some((m) => noDominio(d, m.oficiais)) || WEBMAIL_GRATUITO.has(d) || noDominio(d, HOSPEDAGEM_ABUSADA);
const prioridade = (u) => (u.sinais.length ? 0 : 1);
