const urlhaus = unicos(urls.map((u) => u.host).filter((h) => !conhecido(dominioRegistravel(h)) && !noDominio(h, [...ENCURTADORES])), 5);
const rdap = unicos([de.dominio, responder.dominio, ...urls.map((u) => u.dominio)]
  .filter((d) => d && !ehIPv4(d))
