  blocos.push(`⚠️ <b>O usuário disse que ${esc(ev.interacao.rotulos.join(', '))}</b>` +
    (ev.interacao.trechos.length ? `\n<blockquote>${esc(ev.interacao.trechos[0])}</blockquote>` : ''));
}
