    // Tipos fixos (clicou, senha, anexo, respondeu, pagou), detectados por regra no relato: a resposta ao usuário usa estes.
    interacao_tipos: ['clicou', 'senha', 'anexo', 'respondeu', 'pagou'].filter((t) => ev.interacao[t]),
