// ---- Biblioteca: texto seguro ----
// Tudo o que vem do chamado e do e-mail suspeito foi escrito por um usuário ou por um ATACANTE.
// Por isso: esc() antes de ir para o Telegram/GLPI (vira texto, nunca HTML) e desarmar() nos
// indicadores (hxxps://site[.]com), para o analista não abrir um link malicioso sem querer.

const ENTIDADES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ordm: 'º', ordf: 'ª', euro: '€', copy: '©', reg: '®', ndash: '–', mdash: '—', hellip: '…', laquo: '«', raquo: '»' };
// Letras acentuadas do português: &aacute; &Atilde; &ccedil; ...
for (const [letras, acento, base] of [['aeiou', 'acute', 0x301], ['aeiou', 'grave', 0x300], ['aeiou', 'circ', 0x302], ['aon', 'tilde', 0x303], ['aeiou', 'uml', 0x308], ['c', 'cedil', 0x327]]) {
  for (const l of letras) {
    ENTIDADES[l + acento] = (l + String.fromCharCode(base)).normalize('NFC');
    ENTIDADES[l.toUpperCase() + acento] = (l.toUpperCase() + String.fromCharCode(base)).normalize('NFC');
  }
}

function decodificarEntidades(texto) {
  return String(texto ?? '').replace(/&(#x[0-9a-f]{1,6}|#\d{1,7}|[a-z]{2,8});/gi, (inteiro, e) => {
    if (e[0] === '#') {
      const n = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return n > 0 && n < 0x110000 && !(n >= 0xd800 && n <= 0xdfff) ? String.fromCodePoint(n) : inteiro;
    }
    return ENTIDADES[e] ?? ENTIDADES[e.toLowerCase()] ?? inteiro;
  });
}

// HTML -> texto. O GLPI guarda o conteúdo do chamado com as tags escapadas (&lt;p&gt;): desfaz isso antes.
function htmlParaTexto(html) {
  let s = String(html ?? '');
  if (/&lt;\/?[a-z][\s\S]*?&gt;/i.test(s) && !/<\/?[a-z][^>]*>/i.test(s)) s = decodificarEntidades(s);
  s = s.replace(/<(script|style|head|title)\b[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d|blockquote|table)\s*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ');
  return decodificarEntidades(s)
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Escapa para HTML do Telegram e do GLPI (o Telegram só reconhece &, < e >; " protege atributos).
function esc(texto) {
  return String(texto ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Corta o texto e remove caracteres de controle (mantém quebras de linha).
function curto(texto, maximo = 200) {
  const t = String(texto ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f​-‏‪-‮⁦-⁩]/g, '').trim();
  return t.length > maximo ? t.slice(0, maximo - 1) + '…' : t;
}

// Uma linha só (sem quebras), cortada.
function linha(texto, maximo = 200) {
  return curto(String(texto ?? '').replace(/\s+/g, ' '), maximo);
}

// Indicador "desarmado": https://mal.com/x -> hxxps://mal[.]com/x ; a@mal.com -> a[@]mal[.]com ; 1.2.3.4 -> 1.2.3[.]4
function desarmar(ioc) {
  const texto = String(ioc ?? '');
  const url = texto.match(/^([a-z][a-z0-9+.-]*)(:\/\/)([^/?#]*)(.*)$/i);
  if (url) return url[1].replace(/^http/i, (p) => p[0] + 'xx' + p[3]) + url[2] + url[3].replace(/\./g, '[.]').replace(/@/g, '[@]') + url[4];
  return texto.replace(/@/g, '[@]').replace(/\.(?=[^.]*$)/, '[.]');
}

function unicos(lista, maximo = 50) {
  const vistos = new Set();
  const saida = [];
  for (const item of lista) {
    const chave = String(item).toLowerCase();
    if (!item || vistos.has(chave)) continue;
    vistos.add(chave);
    saida.push(item);
    if (saida.length >= maximo) break;
  }
  return saida;
}
// ---- fim da biblioteca ----

// Nó "Lê as mensagens": transforma o que chegou no Telegram em ações.
//  - Clique num botão do relato (ph|<chamado>|p/l/s/e) -> decidir: phishing, legítimo, spam ou escalar N2.
//  - /nota <chamado> <texto>  -> nota interna no chamado (justificativa, contexto, o que foi feito).
//  - /reanalisar <chamado>    -> o fluxo de análise pega o chamado de novo (ex.: o usuário anexou o .eml depois).
//  - /ajuda                   -> lista os comandos.
// Só vale o que vem do grupo configurado (PHISHING_TELEGRAM_CHAT_ID) e, para decidir ou anotar, só
// analistas autorizados (IDs do Telegram em PHISHING_ANALISTAS). Sem configuração, nada é aceito.
const r = $input.first().json;
if (r.statusCode !== 200 || !r.body?.ok) return []; // 409 = outra leitura em andamento; tenta no próximo minuto
const atualizacoes = Array.isArray(r.body.result) ? r.body.result : [];
if (!atualizacoes.length) return [];

const grupo = String($env.PHISHING_TELEGRAM_CHAT_ID ?? '').trim();
const analistas = new Set(String($env.PHISHING_ANALISTAS ?? '').split(/[\s,;]+/).filter((x) => /^\d{3,20}$/.test(x)));
const DECISOES = { p: 'phishing', l: 'legitimo', s: 'spam', e: 'escalar' };
const AJUDA = 'Comandos do grupo de relatos de phishing\n\n' +
  '👆 Botões da ficha: decidem o caso. Respondem ao usuário e encerram (ou escalam para o N2) o chamado no GLPI.\n\n' +
  '🛡️ Depois de "É phishing", o botão "Bloquear IOCs no Wazuh" manda os domínios, IPs de links e hashes para as listas do Wazuh (por 90 dias). Confira a lista na mensagem antes de clicar.\n\n' +
  '📝 /nota NÚMERO TEXTO: registra no chamado o que você fez, como nota interna (só a equipe técnica vê, o usuário não).\n' +
  'Exemplo: /nota 123 bloqueei o domínio no proxy e no filtro de e-mail\n\n' +
  '🔁 /reanalisar NÚMERO: analisa o chamado de novo (ex.: o usuário anexou o e-mail depois).\n' +
  'Exemplo: /reanalisar 123\n\n' +
  'Só analistas autorizados podem decidir e anotar.';
const pessoa = (de) => ({
  id: String(de?.id ?? ''),
  nome: linha([de?.first_name, de?.last_name].filter(Boolean).join(' ') || 'sem nome', 60),
  usuario: linha(de?.username ?? '', 40),
});

const acoes = [];
const decididosAgora = new Set();
for (const u of atualizacoes) {
  const base = { update_id: Number(u.update_id) };
  const cb = u.callback_query;
  if (cb) {
    const analista = pessoa(cb.from);
    const resposta = (texto, alerta = false) => acoes.push({ ...base, tipo: 'responder', callback_id: String(cb.id), texto, alerta, analista });
    const m = String(cb.data ?? '').match(/^ph\|(\d{1,9})\|([plsexb])$/);
    if (!grupo || String(cb.message?.chat?.id ?? '') !== grupo || !m) { resposta('Botão inválido ou de outro grupo.'); continue; }
    if (m[2] === 'x') { resposta('Este relato já foi decidido.'); continue; }
    if (!analistas.has(analista.id)) { resposta(`Sem permissão para decidir. Peça para incluir o seu ID do Telegram (${analista.id}) em PHISHING_ANALISTAS.`, true); continue; }
    const chamado = Number(m[1]);
    if (m[2] === 'b') {
      // "Bloquear IOCs no Wazuh": só aparece depois de "É phishing"; a trava no Redis garante um envio por chamado.
      if (decididosAgora.has('b' + chamado)) { resposta(`Os IOCs do chamado #${chamado} já estão sendo enviados.`); continue; }
      decididosAgora.add('b' + chamado);
      acoes.push({ ...base, tipo: 'bloquear', chamado_id: chamado, callback_id: String(cb.id), mensagem_id: Number(cb.message.message_id), analista });
      continue;
    }
    if (decididosAgora.has(chamado)) { resposta(`Chamado #${chamado} já está sendo decidido.`); continue; }
    decididosAgora.add(chamado);
    acoes.push({ ...base, tipo: 'decidir', chamado_id: chamado, decisao: DECISOES[m[2]], callback_id: String(cb.id), mensagem_id: Number(cb.message.message_id), analista });
    continue;
  }
  const msg = u.message;
  if (!grupo || !msg || String(msg.chat?.id ?? '') !== grupo) continue; // outras conversas: ignora em silêncio
  const cmd = String(msg.text ?? '').trim().match(/^\/(nota|reanalisar|ajuda|help|start)(?:@\w+)?(?:\s+#?(\d{1,9}))?(?:\s+([\s\S]+))?$/i);
  if (!cmd) continue;
  const analista = pessoa(msg.from);
  const comum = { ...base, mensagem_id: Number(msg.message_id), analista };
  const responder = (texto) => acoes.push({ ...comum, tipo: 'responder', texto });
  const nome = cmd[1].toLowerCase();
  if (['ajuda', 'help', 'start'].includes(nome)) { responder(AJUDA); continue; }
  if (!analistas.has(analista.id)) { responder(`Sem permissão. Peça para incluir o seu ID do Telegram (${analista.id}) em PHISHING_ANALISTAS.`); continue; }
  if (!cmd[2]) { responder(`Informe o número do chamado. Ex.: /${nome} 123${nome === 'nota' ? ' texto da nota' : ''}`); continue; }
  if (nome === 'nota' && !String(cmd[3] ?? '').trim()) { responder(`Escreva o texto da nota. Ex.: /nota ${cmd[2]} usuário confirmou que não clicou`); continue; }
  acoes.push({ ...comum, tipo: nome, chamado_id: Number(cmd[2]), texto: curto(cmd[3] ?? '', 2000) });
}

return [{ json: {
  offset: Math.max(...atualizacoes.map((u) => Number(u.update_id))) + 1,
  acoes: acoes.slice(0, 20),
} }];

// Nó "Separa as ações": um item por ação, com as chaves do Redis que cada uma usa.
//  - trava: decisão = uma por chamado (dois cliques ou dois analistas não encerram duas vezes);
//    outras ações = uma por mensagem do Telegram (não repete se a mesma mensagem chegar de novo).
const prefixo = $('Configuração').first().json.prefixoRedis;
return $('Lê as mensagens').first().json.acoes.map((a, i) => ({ json: {
  ...a,
  chave_analise: `${prefixo}analise:${a.chamado_id ?? 0}`,
  chave_trava: a.tipo === 'decidir' ? `${prefixo}decisao:${a.chamado_id}`
    : a.tipo === 'bloquear' ? `${prefixo}bloqueio:${a.chamado_id}` // um envio ao Wazuh por chamado
      : `${prefixo}update:${a.update_id}`,
}, pairedItem: 0 }));

